for i,line in enumerate(raw.splitlines(),1):
 parts=line.split('|');assert len(parts)==8,(i,len(parts))
 parent,q,*rest=parts;options=rest[:4];answer=[int(x) for x in rest[4].split(',')];explain=rest[5]
 questions.append(dict(id=f'Q-{i:03}',parent=parent,type='multiple' if len(answer)>1 else 'single',question=q,options=options,answer=answer,explanation=explain,origin='自编训练题，非官方真题'))
